import os
from flask import Flask, request, abort, send_file

app = Flask(__name__)
REPORTS = os.path.abspath("./data/reports")

@app.route("/download")
def download():
    filename = request.args.get("filename", "")
    if not filename:
        abort(404)

    # Ensure the path is within REPORTS directory and does not contain .. or .
    safe_path = os.path.join(REPORTS, filename)
    if ".." in safe_path or "." in safe_path:
        abort(403)  # Forbidden

    if not os.path.isfile(safe_path):
        abort(404)

    return send_file(safe_path)
```

