def read_user_file(user_id, filename):
    # Validate inputs to prevent path traversal or directory traversal attacks
    if not user_id:
        raise ValueError("user_id cannot be empty")
    if not filename:
        raise ValueError("filename cannot be empty")

    # Ensure the filename does not contain path separators that could lead outside the intended directory
    if '/' in filename or '\\' in filename:
        raise ValueError("Filename contains invalid characters for safe file access")

    # Construct the full path safely using os.path.join to handle any special characters
    filepath = os.path.join("./userdata/", user_id, filename)

    # Use absolute path with os.path.abspath to ensure we are working within the current directory context
    abs_path = os.path.abspath(filepath)

    # Verify that the constructed path is actually within the intended directory (userdata/)
    if not os.path.isabs(abs_path):
        raise ValueError("Path construction failed: resulting path does not start with ./userdata/")

    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"File not found: {filepath}")

    # Use absolute paths for the file operations to ensure consistency and security
    with open(abs_path, "r", encoding="utf-8") as fh:
        return fh.read()
