#include <stdlib.h>
#include <string.h>

char *build_fullname(const char *first, const char *last) {
    if (first == NULL || last == NULL) {
        return NULL;
    }

    char buf[128];
    size_t len_first = strlen(first);
    size_t len_last = strlen(last);

    // Ensure lengths are within buffer bounds and handle empty strings
    if (len_first + 1 > sizeof(buf)) {
        return NULL;
    }
    if (len_last + 1 > sizeof(buf) - 1) {
        return NULL;
    }

    strcpy(buf, first);
    strcat(buf, " ");
    strcat(buf, last);

    char *full = malloc(strlen(buf) + 1);
    if (full == NULL) {
        return NULL;
    }

    strcpy(full, buf);
    free(buf); // Free the temporary buffer to avoid memory leak

    return full;
}
