    if (eq == NULL) {
        fprintf(stderr, "invalid input\n");
        return 1;
    }

    *eq = '\0';
    strncpy(key, line, sizeof(key) - 1);
    key[sizeof(key) - 1] = '\0';

    strncpy(value, eq + 1, sizeof(value) - 1);
    value[sizeof(value) - 1] = '\0';

    printf("key: %s\n", key);
    printf("value: %s\n", value);

    return 0;
}
